<#
  AI Task Manager - fix the "How often should this task repeat?" loop and slow replies.
  Run from your "backend" folder (the one that contains src\).

  What it changes:
    - Short answers like "everyday", "9 am", "for 2 weeks" are read by the
      backend directly. No Gemini call, so they answer almost instantly.
    - gemini-3.8-flash can't turn thinking off, so the old thinkingBudget:0
      setting was ignored and every call ran at "medium" thinking. It now
      asks for "low".
    - A simpler, flat JSON shape for Gemini, plus the question being answered
      is sent along with the reply.
    - Switching between recurring and repeat-until-done no longer throws away
      what the user already said.
    - The same question is never repeated word-for-word; the second time it
      shows examples.
    - All retries together stop after 40 seconds.
#>

$ErrorActionPreference = "Stop"

if (-not (Test-Path "src\modules\assistant\drafts")) {
  Write-Host "ERROR: run this from your backend folder (the one containing src\)." -ForegroundColor Red
  exit 1
}

$backup = "backup_assistant_{0}" -f (Get-Date -Format "yyyyMMdd_HHmmss")
New-Item -ItemType Directory -Path $backup -Force | Out-Null
Write-Host "Backing up current files to $backup" -ForegroundColor Cyan

$files = [ordered]@{}
$files["src\modules\assistant\slot_filler.py"] = ""
$files["src\modules\assistant\task_parser.py"] = ""
$files["src\modules\assistant\prompts\task_command_prompt.py"] = ""
$files["src\modules\assistant\drafts\service.py"] = ""
$files["src\modules\assistant\providers\gemini_provider.py"] = ""
$files["tests\test_assistant_followups.py"] = ""

foreach ($path in $files.Keys) {
  if (Test-Path $path) {
    $dest = Join-Path $backup $path
    New-Item -ItemType Directory -Path (Split-Path $dest -Parent) -Force | Out-Null
    Copy-Item $path $dest -Force
  }
  $dir = Split-Path $path -Parent
  if ($dir -and -not (Test-Path $dir)) { New-Item -ItemType Directory -Path $dir -Force | Out-Null }
  [System.IO.File]::WriteAllBytes((Join-Path (Get-Location) $path), [Convert]::FromBase64String($files[$path]))
  Write-Host ("  updated  " + $path) -ForegroundColor Green
}

Write-Host ""
python -m compileall -q src
if ($LASTEXITCODE -eq 0) {
  Write-Host "Compile OK." -ForegroundColor Green
  Write-Host "Restart the server:   python -m src.server" -ForegroundColor Green
  Write-Host "Run the new tests:    python -m pytest tests/test_assistant_followups.py -q" -ForegroundColor Green
} else {
  Write-Host "Compile reported a problem - your originals are in $backup" -ForegroundColor Yellow
}
